const leadTotals = `-- name: LeadTotals :one
SELECT count(*) AS total, coalesce(sum(l.deal_value), 0)::bigint AS deal_total
FROM crm.leads l
WHERE l.deleted_at IS NULL AND l.stage = $1::text
  AND ($2::uuid IS NULL OR l.assigned_user_id = $2::uuid)
  AND ($3::uuid[] IS NULL OR l.branch_id = ANY ($3::uuid[]))
  AND ($4::text IS NULL OR l.name ILIKE $4::text OR l.phone ILIKE $4::text
       OR l.code ILIKE $4::text OR l.email::text ILIKE $4::text OR l.parent_name ILIKE $4::text
       OR ($5::text IS NOT NULL AND l.phone_normalized LIKE $5::text))
  AND ($6::uuid IS NULL OR l.branch_id = $6::uuid)
  AND ($7::uuid IS NULL OR l.assigned_user_id = $7::uuid)
  AND ($8::text IS NULL OR l.source = $8::text)
  AND ($9::timestamptz IS NULL OR l.converted_at >= $9::timestamptz)
  AND ($10::timestamptz IS NULL OR l.converted_at <= $10::timestamptz)
`

type LeadTotalsParams struct {
	Stage          string
	ScopeOwner     *uuid.UUID
	ScopeBranches  []uuid.UUID
	Q              *string
	QDigits        *string
	BranchID       *uuid.UUID
	AssignedUserID *uuid.UUID
	Source         *string
	DateFrom       *time.Time
	DateTo         *time.Time
}

type LeadTotalsRow struct {
	Total     int64
	DealTotal int64
}

// Tổng cho màn Đã chốt: số khách và tổng giá trị hợp đồng theo cùng bộ lọc (không phân trang).
func (q *Queries) LeadTotals(ctx context.Context, arg LeadTotalsParams) (LeadTotalsRow, error) {
	row := q.db.QueryRow(ctx, leadTotals,
		arg.Stage,
		arg.ScopeOwner,
		arg.ScopeBranches,
		arg.Q,
		arg.QDigits,
		arg.BranchID,
		arg.AssignedUserID,
		arg.Source,
		arg.DateFrom,
		arg.DateTo,
	)
	var i LeadTotalsRow
	err := row.Scan(&i.Total, &i.DealTotal)
	return i, err
}

