const listLeads = `-- name: ListLeads :many


SELECT l.id, l.code, l.name, l.phone, l.parent_name, l.parent_phone, l.email, l.source, l.stage, l.course_interest,
       l.deal_value, l.branch_id, l.assigned_user_id, l.appointment_at, l.appointment_type, l.next_follow_up_at,
       l.lost_reason, l.lost_at, l.converted_at, l.converted_student_id, l.notes, l.created_at, l.updated_at,
       b.name AS branch_name, u.full_name AS assigned_user_name, l.last_care_at,
       coalesce(ec.class_name, '')::text AS class_name, ec.confirmed_at AS enrollment_confirmed_at,
       count(*) OVER () AS total
FROM crm.leads l
LEFT JOIN core.branches b ON b.id = l.branch_id
LEFT JOIN iam.users u ON u.id = l.assigned_user_id
LEFT JOIN LATERAL (SELECT c.class_name, c.confirmed_at FROM crm.enrollment_confirmations c
    WHERE c.lead_id = l.id AND c.status <> 'cancelled' ORDER BY c.enrolled_at DESC LIMIT 1) ec ON true
WHERE l.deleted_at IS NULL
  AND ($1::uuid IS NULL OR l.assigned_user_id = $1::uuid)
  AND ($2::uuid[] IS NULL OR l.branch_id = ANY ($2::uuid[]))
  AND ($3::text IS NULL OR l.name ILIKE $3::text OR l.phone ILIKE $3::text
       OR l.code ILIKE $3::text OR l.email::text ILIKE $3::text OR l.parent_name ILIKE $3::text
       OR ($4::bool AND l.lost_reason ILIKE $3::text)
       OR ($5::text IS NOT NULL AND (l.phone_normalized LIKE $5::text
           OR l.parent_phone ILIKE $3::text
           OR regexp_replace(coalesce(l.parent_phone, ''), '[ .-]', '', 'g') LIKE $5::text)))
  AND ($6::uuid IS NULL OR l.branch_id = $6::uuid)
  AND ($7::uuid IS NULL OR l.assigned_user_id = $7::uuid)
  AND ($8::text IS NULL OR l.source = $8::text)
  AND ($9::text IS NULL OR l.stage = $9::text)
  AND ($10::timestamptz IS NULL OR (CASE $11::text
        WHEN 'converted_at' THEN l.converted_at WHEN 'lost_at' THEN l.lost_at ELSE l.created_at END) >= $10::timestamptz)
  AND ($12::timestamptz IS NULL OR (CASE $11::text
        WHEN 'converted_at' THEN l.converted_at WHEN 'lost_at' THEN l.lost_at ELSE l.created_at END) <= $12::timestamptz)
  AND (NOT $13::bool OR (l.stage = 'new' AND l.created_at <= $14::timestamptz
        AND l.last_care_at IS NULL))
  AND (NOT $15::bool OR (l.stage IN ('new', 'consulting', 'test_scheduled', 'testing', 'tested', 'result_sent')
        AND l.next_follow_up_at IS NOT NULL AND l.next_follow_up_at <= $16::timestamptz
        AND (l.last_care_at IS NULL OR l.last_care_at < l.next_follow_up_at)))
  AND (NOT $17::bool OR (l.appointment_at BETWEEN $18::timestamptz AND $16::timestamptz
        AND l.stage NOT IN ('lost', 'waiting_class', 'won')))
ORDER BY
  CASE WHEN $19::text = 'follow_up' THEN l.next_follow_up_at END ASC NULLS LAST,
  CASE WHEN $19::text = 'test_today' THEN l.appointment_at END ASC NULLS LAST,
  CASE WHEN $19::text = 'converted' THEN l.converted_at END DESC NULLS LAST,
  CASE WHEN $19::text = 'lost' THEN l.lost_at END DESC NULLS LAST,
  CASE WHEN $19::text IN ('converted', 'lost') THEN l.created_at END DESC,
  l.updated_at DESC, l.id DESC
LIMIT $21 OFFSET $20
`

